const routeValidators = [{name:'notEmpty'},{name:'isEmail'}];
const validators = routeValidators.map(v => reg.get(v.name)).filter(v => v) as Validator[];
// per-field validation example
const results = await Promise.all(validators.map(v => v.validate(input[fieldName])));
